def custom_jacobi_symbols(a: int, n: int) -> int:
    if n <= 0 or n % 2 == 0:
        raise ValueError("n must be a positive odd integer")

    result = 1
    a = a % n

    while a != 0:
        while a % 2 == 0:
            a //= 2
            if n % 8 == 3 or n % 8 == 5:
                result = -result

        a, n = n, a
        if a % 4 == 3 and n % 4 == 3:
